# AUTOGENERATED KERNEL (LLM)
# Source: LLM-generated candidate implementation
# Status: Experimental / uncurated
# Expectation: Correctness-first, performance not representative

import torch
import torch.nn as nn
import triton
import triton.language as tl


@triton.autotune(
    configs=[
        triton.Config(
            {"BLOCK_SIZE": 4096, "NUM_PROGRAMS": 256}, num_warps=8, num_stages=3
        ),
        triton.Config(
            {"BLOCK_SIZE": 8192, "NUM_PROGRAMS": 256}, num_warps=16, num_stages=3
        ),
        triton.Config(
            {"BLOCK_SIZE": 8192, "NUM_PROGRAMS": 512}, num_warps=16, num_stages=3
        ),
        triton.Config(
            {"BLOCK_SIZE": 4096, "NUM_PROGRAMS": 512}, num_warps=8, num_stages=2
        ),
        triton.Config(
            {"BLOCK_SIZE": 16384, "NUM_PROGRAMS": 256}, num_warps=16, num_stages=3
        ),
    ],
    key=["n_elements"],
)
@triton.jit
def relu_kernel_persistent(
    x_ptr,
    output_ptr,
    n_elements,
    BLOCK_SIZE: tl.constexpr,
    NUM_PROGRAMS: tl.constexpr,
):
    pid = tl.program_id(0)
    num_blocks = tl.cdiv(n_elements, BLOCK_SIZE)

    for block_id in tl.range(pid, num_blocks, NUM_PROGRAMS):
        block_start = block_id * BLOCK_SIZE
        offsets = block_start + tl.arange(0, BLOCK_SIZE)
        mask = offsets < n_elements
        x = tl.load(x_ptr + offsets, mask=mask)
        output = tl.maximum(x, 0.0)
        tl.store(output_ptr + offsets, output, mask=mask)


class Model(nn.Module):
    def __init__(self):
        super(Model, self).__init__()

    def forward(self, x: torch.Tensor) -> torch.Tensor:
        output = torch.empty_like(x)
        n_elements = x.numel()
        grid = lambda META: (META["NUM_PROGRAMS"],)
        relu_kernel_persistent[grid](x, output, n_elements)
        return output
